from copy import deepcopy
from taf.rfrl.procedures.resources.python.logger import log_input_and_output
from taf.rfrl.procedures.resources.python.admin_info_model.admin_info_model import is_iot_cell


@log_input_and_output
def get_called_cells_from_ues_and_cells(ues_and_cells):
    """
    Returns a list of all called cells included in cells_to_ues dict,
    or an empty list if ues_and_cells is empty
    :param ues_and_cells: serial numbers of UES with assigned list of
                          configuration distnames of cells to be called, e.g.:
                          ues_and_cells = {"SN1234": ["MRBTS-1234/NRCELL-2", "MRBTS-1234/NRCELL-22"],
                                           "SN4321": ["MRBTS-1234/NRCELL-1, MRBTS-1234/NRCELL-2"]}
    :type ues_and_cells: dict(str, list(str)) or None
    :returns: list of configuration distnames of cells, e.g. ["MRBTS-1234/NRCELL-2",
                                                              "MRBTS-1234/NRCELL-22",
                                                              "MRBTS-1234/NRCELL-1",
                                                              "MRBTS-1234/NRCELL-2"]
    :rtype: list(str) or empty list
    """
    if not ues_and_cells:
        return []
    return [cell for ue_serial_number, cells in ues_and_cells.items() for cell in cells]


@log_input_and_output
def get_list_of_unique_ues_paired_with_cells(ues_and_cells):
    """
    Returns list of dictionaries containing unique UEs paired with cells or
    empty list if ues_and_cells is empty.
    This format makes it possible to use `make_l3_call_to_selected_cells_using_selected_ues`
    from taf.rfrl.l3_call
    :param ues_and_cells: serial numbers of UES with assigned list of
                          configuration distnames of cells to be called, e.g.:
                          ues_and_cells = {"SN1234": ["MRBTS-1234/NRCELL-2", "MRBTS-1234/NRCELL-22"],
                                           "SN4321": ["MRBTS-1234/NRCELL-1"]}
    :type ues_and_cells: dict(str, list(str)) or None
    :returns: list of UEs paired with cells, e.g.  [{"MRBTS-1234/NRCELL-2":"SN1234", "MRBTS-1234/NRCELL-1":"SN4321"},
                                                   {"MRBTS-1234/NRCELL-22":"SN1234"}]

    :rtype: list(dict(str, str)) or empty list
    """
    if not ues_and_cells:
        return []

    unique_pairs = []
    for ue_serial_number, cells_distname in ues_and_cells.items():
        for index, cell_distname in enumerate(cells_distname):
            try:
                unique_pairs[index][cell_distname] = ue_serial_number
            except IndexError:
                unique_pairs.append({cell_distname: ue_serial_number})

    return unique_pairs


@log_input_and_output
def get_ue_pairs_for_specific_cell_distnames(ues_and_cells, cell_distnames):
    """
    Returns list of dictionaries containing UEs paired with specific cells given
    by cell_distnames. Empty list is returned if no UE can be paired with any cell
    or if ues_and_cells is empty.
    :param ues_and_cells: serial numbers of UES with assigned list of
                          configuration distnames of cells to be called, e.g.:
                          ues_and_cells = {"SN1234": ["MRBTS-1234/NRCELL-2", "MRBTS-1234/NRCELL-22"],
                                           "SN4321": ["MRBTS-1234/NRCELL-1"]}
    :type ues_and_cells: dict(str, list(str)) or None
    :param cell_distnames: list of cells for which pairs should be returned, e.g. ["MRBTS-1234/NRCELL-2",
                                                                                   "MRBTS-1234/NRCELL-22"]
    :type cell_distnames: list(str)
    :returns: list of UEs paired with cells, i.e. [{"MRBTS-1234/NRCELL-2":"SN1234"},
                                                   {"MRBTS-1234/NRCELL-22":"SN1234"}]
    :rtype: list(dict(str, str)) or empty list
    """
    if not ues_and_cells:
        return []

    pairs_for_cells = []
    for ue_serial_number, cells_distname in ues_and_cells.items():
        for index, cell_distname in enumerate(cell_distnames):
            if cell_distname in cells_distname:
                try:
                    if cell_distname in pairs_for_cells[index]:
                        pairs_for_cells.append({cell_distname: ue_serial_number})
                    else:
                        pairs_for_cells[index][cell_distname] = ue_serial_number
                except IndexError:
                    pairs_for_cells.append({cell_distname: ue_serial_number})

    return pairs_for_cells


def extract_iot_cells_from_ues_and_cells(ues_and_cells, connection):
    """
    Extracts IoT cells from ues_and_cells dictionary and returns two separate dicts:
    one without IoT cells and one with IoT cells. If ues_and_cells is None or empty, two empty dicts are returned.
    IoT cells are identified via admin info model.
    :param ues_and_cells: serial numbers of UES with assigned list of configuration distnames of cells to be called, e.g.:
                          ues_and_cells = {"SN1234": ["MRBTS-1234/LNCEL-1", "MRBTS-1234/LNCEL-2"],
                                           "SN4321": ["MRBTS-1234/NRCELL-1"]}
    :type ues_and_cells: dict(str, list(str)) or None
    :param connection: connection alias to be used for API calls
    :type connection: str

    :returns: two dicts, one without IoT cells and one with IoT cells, e.g.:
          ({"SN1234": ["MRBTS-1234/LNCEL-2"], "SN4321": ["MRBTS-1234/NRCELL-1"]},
           {"SN1234": ["MRBTS-1234/LNCEL-1"]})
    :rtype: tuple(dict(str, list(str)), dict(str, list(str))) or tuple(empty dict, empty dict)
    """
    if ues_and_cells is None:
        return {}, {}

    ues_and_cells_with_iot = {}
    ues_and_cells_without_iot = {}
    for ue, cells in ues_and_cells.items():
        for cell in cells:
            if "LNCEL" in cell and is_iot_cell(cell_type="lte", cell_id=cell.split("-")[-1], connection=connection):
                if ues_and_cells_with_iot.get(ue):
                    ues_and_cells_with_iot[ue].append(cell)
                else:
                    ues_and_cells_with_iot[ue] = [cell]
            else:
                if ues_and_cells_without_iot.get(ue):
                    ues_and_cells_without_iot[ue].append(cell)
                else:
                    ues_and_cells_without_iot[ue] = [cell]

    return ues_and_cells_without_iot, ues_and_cells_with_iot


def remove_gsm_and_wcdma_cells_from_called_cells(called_cells):
    """
    Checks if there are any cells of GSM or WCDMA technology in
    the list of called_cells and removes them from the list.
    :param called_cells: list of called cells distnames
    :type called_cells: list
    """
    called_cells_distnames = deepcopy(called_cells)
    for called_cell in called_cells:
        if "WNCEL" in called_cell or "GNCEL" in called_cell:
            called_cells_distnames.remove(called_cell)

    return called_cells_distnames


@log_input_and_output
def is_lte_iot_cell(cell_distname, connection):
    """
    Checks if the given cell distname is of LTE IoT type.
    :param cell_distname: cell distname to check type, e.g.: "MRBTS-50146/NRBTS-1/NRCELL-1"
    :type cell_distname: str
    :param connection: connection alias to be used for API calls
    :type connection: str
    :returns: True if cell is LTE IoT type, False otherwise
    :rtype: bool
    """
    if "LNCEL" in cell_distname:
        return is_iot_cell(cell_type="lte", cell_id=cell_distname.split("-")[-1], connection=connection)

    return False


def get_cell_distname_from_cell_to_ue_dict(cell_to_ue):
    """
    Returns cell distname from cell_to_ue dictionary.
    :param cell_to_ue: dict with cell distname as key and ue serial number as value,
                       e.g.: {"MRBTS-50146/NRBTS-1/NRCELL-1": "SN1234"}
    :type cell_to_ue: dict
    :returns: cell distname
    :rtype: str
    """
    return list(cell_to_ue)[0]
